content:
[public_service] {
  "entrance_lobby": {
    "flow_strategy": "采用单向递进式的入馆序列，从外至内依次布置售票/取票 → 智能安检 → 存包 → 检票。队列通过可伸缩栏距和缓冲带形成蛇形队列；检票后可进入“预检票等待区”，实现分区释放进入中庭以控制瞬时人流。VIP/亲子/轮椅客群设独立优先通道与侧向分流。上下层立体组织：地面层为主流线层，设置核心大厅与导引中心；二层设连廊与可俯瞰中庭的“预检票区”，在高峰时开启双层入场以提升承载力，避免正面拥堵。动线全程可见导向装置、导引灯带与动态人数显示屏，支持现场动态引流与应急疏散。",
    "spatial_requirements": "门厅/综合大厅净高不低于8–10m以保证视线与通风；中心大厅单层面积建议1,200–1,800m²，能同时容纳1,000–1,200人峰值（按人均0.8–1.2m²计算）。外立面及导流墙面采用高辨识度色彩与图形化导引，顶部设置高吊装置与点状灯具强化空间纵深；近入口设置“迎宾雕塑/科技装置”作为视觉锚点，既可指引方向亦提升到访体验。",
    "key_facilities": [
      "智能票务与取票机群（分散布置减少排队交叉）",
      "排队管理系统（闸机+蛇形隔离栏+预检票缓冲区）",
      "安检设备（双通道X光机+手持金属探测+必要时的人工安检点）",
      "自助存包柜/储物室（双区布局：临时寄存与日间寄存区分）",
      "综合咨询台（前台+数字导览台+人工咨询窗口）",
      "无障碍服务台与优先通道",
      "失物招领台",
      "现场动态信息显示牌（含等待时长与分流提示）",
      "应急广播/紧急按钮"
    ]
  },
  "amenities_standard": {
    "restroom_config": "按参观峰值人群估算配比，女卫:男卫≈2:1；每个楼层设置至少1处第三卫生间以满足无障碍与家庭需求。坐便器与洗手盆总量按峰值女性≥1个/20人、男性≥1个/30人（含小便器）配置，并预留20–25%冗余供高峰。洗手干区与排队区分离，避免回流冲突。",
    "accessibility": "全馆无障碍贯通：坡道坡度≤1:12，采用双侧扶手与中间防滑盲道；电梯最小轿厢尺寸1,100×1,400mm，配备盲文/语音提示；地面铺装采用高对比度导向纹理与触觉铺砖；服务窗口设置低位咨询台（≤850mm高）与无障碍座位；卫生间内配备无障碍隔间与可移动儿童座椅；必要时提供导盲犬服务与听障手语服务台。",
    "special_care": "母婴室：按展馆面积每3,000m²设置一处，单间≥6–8m²，配备婴儿护理台、微波炉、洗烘一体机、哺乳座椅、储奶柜与紧急呼叫系统，临近女性卫生间布置。医务室：设置于易达性较好处，配备急救包、自动体外除颤器（AED）、简易诊疗床与紧急报警，支持对高强度项目的健康提醒与临时救护。"
  },
  "commercial_dining": [
    {
      "type": "餐饮/咖啡",
      "location": "建议靠近出口必经动线的末端，设置独立出入口便于闭馆后对外运营；同时可在顶层或靠近景观面的位置布置屋顶咖啡/观景餐饮区，作为高峰期的分流点与情绪“缓冲地”。",
      "design_note": "厨房分区独立且满足餐饮油烟与排烟规范，预留给排风口与降噪措施；就餐区与展陈区声学分隔，降低噪音声压峰值；座位布局支持快取与堂食双模式，兼顾高峰与高峰后的效率；设无障碍餐桌与儿童高度餐台；对夜场活动采用可分区独立的照明与空调策略以节省能耗。",
      "design_note": "（如需同时布置屋顶咖啡）屋顶结构与幕墙需满足风荷载与防晒雨棚，餐位设可移动家具并预留应急疏散通道；采用高可见度导引从中庭指向屋顶餐饮区，缓解首层拥堵。"
    },
    {
      "type": "文创商店",
      "location": "最优布置在检票后至出口的必经路径中段或检票后至中庭的关键转角处，保证动线连贯；与展陈主题空间形成“主题延展”，提高转化率。",
      "design_note": "采用“半开放+半围合”的布置，避免形成死角与遮挡疏散通道；货架与结账台遵循人行宽度与无障碍间距要求，设3–4台自助收银机与2个人工收银位；陈列区按主题模块化，便于不同特展快速更换；设置小型仓储与补货通道，避免干扰人流；商品与动线交叉区域设置防滑防倾倒措施与应急照明。"
    }
  ],
  "rest_area_concept": "在核心中庭边缘与次级中庭设置“静噪座椅岛”，利用绿植墙、软靠背座椅与低分贝声环境打造“情绪缓冲区”。每100m主走廊至少设置一处安静角落，配备双座/三人座、带USB与手机充电插座，并邻近无障碍卫生间与亲子设施。设置“科普轻内容屏”（短视频/音频）与“知识导引墙”，让等待成为信息补给而非拥堵焦虑；在二层连廊或景观面布置“观景廊椅”与可坐靠的栏杆座面，承载高频短时停留需求。”
}
